import json
import os

workspace = '/home/USER/runs/paper/qwen-h-u1-turns/frozen/seen/play/users/u026/system/state/workspace'

# Look for files that might contain answers with background 6
found_match = False
for fname in sorted(os.listdir(workspace)):
    if fname.endswith('.json') and 'submit' in fname.lower():
        fpath = os.path.join(workspace, fname)
        try:
            with open(fpath, 'r') as f:
                data = json.load(f)
                # Check if this is a grid submission
                if isinstance(data, dict) and 'grid' in data:
                    grid = data['grid']
                    if len(grid) > 0:
                        # Count background values 
                        sample = grid[0]
                        bg_candidates = {v: sample.count(v) for v in set(sample[:10])}
                        if len(bg_candidates) > 0:
                            if all(bg_candidates[k] > 0 for k in bg_candidates):
                                # Check for background 6 patterns
                                if any(0 <= v <= 15 for v in sample[:5]):
                                    # Check if grid has background=6 throughout
                                    bg_count = 0
                                    for row in grid:
                                        bg_count += row.count(6)
                                    total = sum(len(row) for row in grid)
                                    if total > 0 and bg_count > total * 0.5:
                                        priorities = ["- " + fname]
                                        priorities.sort(reverse=True)
                                        found_match = True
                                        print("\n".join(priorities))
        except:
            pass
print(f"\nSearch complete. Found {found_match} potential background patterns")

